{
  "apiVersion": "gateway.api-platform.wso2.com/v1",
  "kind": "LlmProvider",
  "metadata": {
    "name": "ff-openai"
  },
  "spec": {
    "displayName": "Fault flows - provider with policies",
    "version": "v1.0",
    "template": "openai",
    "context": "/ff-openai",
    "upstream": {
      "url": "{{mockUpstream}}/v1"
    },
    "accessControl": {
      "mode": "allow_all"
    },
    "policies": [
      {
        "name": "word-count-guardrail",
        "version": "v1",
        "paths": [
          {
            "path": "/chat/completions",
            "methods": [
              "POST"
            ],
            "params": {
              "request": {
                "enabled": true,
                "min": 1,
                "max": 5,
                "jsonPath": "$.prompt"
              },
              "response": {
                "enabled": true,
                "min": 1,
                "max": 20,
                "jsonPath": "$.choices[0].message.content"
              }
            }
          }
        ]
      },
      {
        "name": "respond",
        "version": "v1",
        "paths": [
          {
            "path": "/edge/rest-body",
            "methods": [
              "GET"
            ],
            "params": {
              "statusCode": 403,
              "body": "{\"error\":\"Forbidden\",\"message\":\"Caller is not allowed to use this model\"}",
              "headers": [
                {
                  "name": "content-type",
                  "value": "application/json"
                }
              ]
            }
          }
        ]
      },
      {
        "name": "respond",
        "version": "v1",
        "paths": [
          {
            "path": "/edge/plain-text",
            "methods": [
              "GET"
            ],
            "params": {
              "statusCode": 429,
              "body": "Slow down, quota exhausted",
              "headers": [
                {
                  "name": "content-type",
                  "value": "text/plain"
                }
              ]
            }
          }
        ]
      },
      {
        "name": "respond",
        "version": "v1",
        "paths": [
          {
            "path": "/edge/openai-body",
            "methods": [
              "GET"
            ],
            "params": {
              "statusCode": 400,
              "body": "{\"error\":{\"message\":\"Bad model\",\"type\":\"invalid_request_error\",\"param\":\"model\",\"code\":\"model_not_found\"}}",
              "headers": [
                {
                  "name": "content-type",
                  "value": "application/json"
                }
              ]
            }
          }
        ]
      },
      {
        "name": "respond",
        "version": "v1",
        "paths": [
          {
            "path": "/edge/empty",
            "methods": [
              "GET"
            ],
            "params": {
              "statusCode": 503,
              "body": "",
              "headers": [
                {
                  "name": "content-type",
                  "value": "application/json"
                }
              ]
            }
          }
        ]
      }
    ]
  }
}

