{
  "apiVersion": "gateway.api-platform.wso2.com/v1",
  "kind": "RestApi",
  "metadata": {
    "name": "ff-rest"
  },
  "spec": {
    "displayName": "Fault flows - REST contrast",
    "version": "v1.0",
    "context": "/ff-rest/$version",
    "upstream": {
      "main": {
        "url": "{{mockUpstream}}"
      }
    },
    "operations": [
      {
        "method": "POST",
        "path": "/chat/completions"
      },
      {
        "method": "GET",
        "path": "/edge/rest-body",
        "policies": [
          {
            "name": "respond",
            "version": "v1",
            "params": {
              "statusCode": 403,
              "body": "{\"error\":\"Forbidden\",\"message\":\"Caller is not allowed to use this model\"}",
              "headers": [
                {
                  "name": "content-type",
                  "value": "application/json"
                }
              ]
            }
          }
        ]
      }
    ]
  }
}

{
  "apiVersion": "gateway.api-platform.wso2.com/v1",
  "kind": "LlmProvider",
  "metadata": {
    "name": "ff-sdk"
  },
  "spec": {
    "displayName": "Fault flows - SDK faults and fault policies",
    "version": "v1.0",
    "template": "openai",
    "context": "/ff-sdk",
    "upstream": {
      "url": "{{mockUpstream}}/v1"
    },
    "accessControl": {
      "mode": "allow_all"
    },
    "operationPolicies": [
      {
        "name": "sample-sdk-fault",
        "version": "v0",
        "paths": [
          {
            "path": "/sdk/plain",
            "methods": [
              "GET"
            ],
            "params": {
              "statusCode": 401,
              "code": "900901",
              "type": "authentication",
              "message": "Invalid API key",
              "description": "internal: key hash mismatch for tenant t-42"
            }
          }
        ]
      },
      {
        "name": "sample-sdk-fault",
        "version": "v0",
        "paths": [
          {
            "path": "/sdk/fallback",
            "methods": [
              "GET"
            ],
            "params": {
              "statusCode": 401,
              "code": "900901",
              "type": "authentication",
              "message": "Invalid API key",
              "description": "internal: key hash mismatch for tenant t-42",
              "fallbackBody": "{\"legacy\":\"fallback body the gateway must not send\"}"
            }
          }
        ]
      },
      {
        "name": "sample-sdk-fault",
        "version": "v0",
        "paths": [
          {
            "path": "/sdk/guardrail",
            "methods": [
              "GET"
            ],
            "params": {
              "statusCode": 422,
              "code": "906001",
              "type": "guardrail",
              "message": "Prompt blocked by content policy",
              "guardrail": {
                "interveningGuardrail": "sample-guardrail",
                "action": "GUARDRAIL_INTERVENED",
                "actionReason": "Blocked category: Hate",
                "assessments": {
                  "categories": [
                    {
                      "category": "Hate",
                      "severity": 4
                    }
                  ]
                }
              }
            }
          }
        ]
      },
      {
        "name": "sample-sdk-fault",
        "version": "v0",
        "paths": [
          {
            "path": "/sdk/response",
            "methods": [
              "GET"
            ],
            "params": {
              "phase": "response",
              "statusCode": 422,
              "type": "guardrail",
              "message": "Completion blocked",
              "guardrail": {
                "interveningGuardrail": "sample-response-guardrail",
                "action": "GUARDRAIL_INTERVENED",
                "actionReason": "Unsafe completion"
              }
            }
          }
        ]
      },
      {
        "name": "sample-sdk-fault",
        "version": "v0",
        "paths": [
          {
            "path": "/fp/stamp",
            "methods": [
              "GET"
            ],
            "params": {
              "statusCode": 401,
              "code": "900901",
              "type": "authentication",
              "message": "Invalid API key",
              "description": "internal: key hash mismatch for tenant t-42"
            }
          }
        ]
      },
      {
        "name": "sample-sdk-fault",
        "version": "v0",
        "paths": [
          {
            "path": "/fp/redescribe",
            "methods": [
              "GET"
            ],
            "params": {
              "statusCode": 401,
              "code": "900901",
              "type": "authentication",
              "message": "Invalid API key",
              "description": "internal: key hash mismatch for tenant t-42"
            }
          }
        ]
      },
      {
        "name": "sample-sdk-fault",
        "version": "v0",
        "paths": [
          {
            "path": "/fp/replace",
            "methods": [
              "GET"
            ],
            "params": {
              "statusCode": 401,
              "code": "900901",
              "type": "authentication",
              "message": "Invalid API key",
              "description": "internal: key hash mismatch for tenant t-42"
            }
          }
        ]
      },
      {
        "name": "sample-sdk-fault",
        "version": "v0",
        "paths": [
          {
            "path": "/fp/body",
            "methods": [
              "GET"
            ],
            "params": {
              "statusCode": 401,
              "code": "900901",
              "type": "authentication",
              "message": "Invalid API key",
              "description": "internal: key hash mismatch for tenant t-42"
            }
          }
        ]
      },
      {
        "name": "sample-sdk-fault",
        "version": "v0",
        "paths": [
          {
            "path": "/fp/status",
            "methods": [
              "GET"
            ],
            "params": {
              "statusCode": 401,
              "code": "900901",
              "type": "authentication",
              "message": "Invalid API key",
              "description": "internal: key hash mismatch for tenant t-42"
            }
          }
        ]
      },
      {
        "name": "respond",
        "version": "v1",
        "paths": [
          {
            "path": "/fp/legacy",
            "methods": [
              "GET"
            ],
            "params": {
              "statusCode": 403,
              "body": "{\"error\":\"Forbidden\",\"message\":\"Caller is not allowed to use this model\"}",
              "headers": [
                {
                  "name": "content-type",
                  "value": "application/json"
                }
              ]
            }
          }
        ]
      },
      {
        "name": "word-count-guardrail",
        "version": "v1",
        "paths": [
          {
            "path": "/fp/guardrail",
            "methods": [
              "POST"
            ],
            "params": {
              "request": {
                "enabled": true,
                "min": 1,
                "max": 5,
                "jsonPath": "$.prompt"
              }
            }
          }
        ]
      }
    ],
    "operationFaultPolicies": [
      {
        "name": "sample-fault-handler",
        "version": "v0",
        "paths": [
          {
            "path": "/fp/stamp",
            "methods": [
              "GET"
            ],
            "params": {
              "fault": {}
            }
          }
        ]
      },
      {
        "name": "sample-fault-handler",
        "version": "v0",
        "paths": [
          {
            "path": "/fp/redescribe",
            "methods": [
              "GET"
            ],
            "params": {
              "fault": {
                "message": "Re-described by the fault policy",
                "code": "999001"
              }
            }
          }
        ]
      },
      {
        "name": "sample-fault-handler",
        "version": "v0",
        "paths": [
          {
            "path": "/fp/replace",
            "methods": [
              "GET"
            ],
            "params": {
              "fault": {
                "code": "999002",
                "inherit": false
              }
            }
          }
        ]
      },
      {
        "name": "sample-fault-handler",
        "version": "v0",
        "paths": [
          {
            "path": "/fp/body",
            "methods": [
              "GET"
            ],
            "params": {
              "fault": {
                "body": "{\"custom\":\"fault policy body\"}"
              }
            }
          }
        ]
      },
      {
        "name": "sample-fault-handler",
        "version": "v0",
        "paths": [
          {
            "path": "/fp/status",
            "methods": [
              "GET"
            ],
            "params": {
              "fault": {
                "statusCode": 429,
                "type": "throttling",
                "message": "Slow down (fault policy)"
              }
            }
          }
        ]
      },
      {
        "name": "sample-fault-handler",
        "version": "v0",
        "paths": [
          {
            "path": "/fp/legacy",
            "methods": [
              "GET"
            ],
            "params": {
              "fault": {
                "message": "Forbidden (re-described)",
                "code": "999003"
              }
            }
          }
        ]
      },
      {
        "name": "sample-fault-handler",
        "version": "v0",
        "paths": [
          {
            "path": "/fp/guardrail",
            "methods": [
              "POST"
            ],
            "params": {
              "fault": {
                "code": "999004"
              }
            }
          }
        ]
      }
    ]
  }
}

